RW2_docker_compose_resources.invariants_dsl:
spec ServiceResources {
    field cpu_reservation: Number {
        value >= 0.1;
        value <= 32.0;
    }
    field cpu_limit: Number {
        value >= this.cpu_reservation;
        value <= 64.0;
    }
    field memory_reservation_mb: Integer {
        value >= 64;
        value <= 65536;
    }
    field memory_limit_mb: Integer {
        value >= this.memory_reservation_mb;
        value <= 131072;
    }
    field restart_policy: String {
        value IN ["no", "always", "on-failure", "unless-stopped"];
    }
}

RW2_rds_storage_autoscaling.invariants_dsl:
spec RDSInstance {
    field engine: String {
        value IN ["mysql", "postgres", "mariadb", "sqlserver-ex", "oracle-se2"];
    }
    field allocated_storage_gb: Integer {
        value >= 20;
        value <= 65536;
    }
    field max_allocated_storage_gb: Integer {
        value >= this.allocated_storage_gb;
        value <= 65536;
    }
    field multi_az: Boolean {}
}

RW2_branch_protection_rule.invariants_dsl:
spec BranchProtectionRule {
    field required_approving_review_count: Integer {
        value >= 0;
        value <= 6;
    }
    field require_code_owner_reviews: Boolean {}
    field enforce_admins: Boolean {}
    field required_status_check: String {
        value IN ["ci/build", "ci/test", "ci/lint", "ci/security-scan"];
    }
}

RW2_monitoring_alert_rule.invariants_dsl:
spec AlertRule {
    field metric_name: String {
        value IN ["cpu_utilization", "memory_utilization", "disk_io_wait", "error_rate", "request_latency_p99"];
    }
    field warning_threshold: Number {
        value >= 0.0;
        value <= 100.0;
    }
    field critical_threshold: Number {
        value >= this.warning_threshold;
        value <= 100.0;
    }
    field evaluation_window_seconds: Integer {
        value >= 30;
        value <= 3600;
    }
}
